options.styles:
.cr { display: flex; flex-wrap: wrap; align-items: center; gap: 24px; height: 100%;
  font-family: Inter, sans-serif; color: #E7ECF3; }
.lbl { font-size: 11px; letter-spacing: .12em; text-transform: uppercase; color: #8D99AB; font-weight: 600; }
.num { font-family: 'Roboto Mono', 'JetBrains Mono', ui-monospace, monospace; font-variant-numeric: tabular-nums; }
.ring { position: relative; width: 168px; height: 168px; flex: none; }
.ring svg { width: 168px; height: 168px; }
.track { fill: none; stroke: #1A222D; stroke-width: 12; }
.arc { fill: none; stroke-width: 12; stroke-linecap: round; }
.arc.ok { stroke: #34D399; } .arc.warn { stroke: #FBBF24; } .arc.crit { stroke: #FB7185; }
.mid { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.mid .num { font-size: 44px; font-weight: 600; line-height: 1; }
.mid .lbl { margin-top: 6px; }
.lbl.ok { color: #34D399; } .lbl.warn { color: #FBBF24; } .lbl.crit { color: #FB7185; }
.checks { flex: 1 1 200px; display: flex; flex-direction: column; gap: 12px; }
.check { display: flex; align-items: center; gap: 10px; font-size: 14px; }
.check .name { flex: 1; color: #C9D2DE; }
.check .word { font-size: 11px; color: #8D99AB; width: 44px; text-align: right; }
.dot { width: 8px; height: 8px; border-radius: 50%; flex: none; }
.dot.ok { background: #34D399; } .dot.warn { background: #FBBF24; } .dot.crit { background: #FB7185; }

options.getOption:
const rows = [];
context.panel.data.series.forEach((s) => {
  const ep = s.fields.find((f) => f.name === 'entrypoint');
  const sv = s.fields.find((f) => f.name === 'service');
  const v = s.fields.find((f) => f.type === 'number');
  if (!ep || !sv || !v) return;
  for (let i = 0; i < v.values.length; i++) rows.push([ep.values[i], sv.values[i], v.values[i]]);
});
const live = rows.filter((r) => r[0] && r[1] && r[2] > 0);
if (!live.length) {
  return { title: { text: 'No requests in this range', left: 'center', top: 'middle',
    textStyle: { color: '#8D99AB', fontSize: 13, fontWeight: 'normal' } } };
}
const colour = { websecure: '#60A5FA', internal: '#F59E0B', web: '#8D99AB' };
const entry = new Set(live.map((r) => r[0]));
const names = new Set();
live.forEach((r) => { names.add(r[0]); names.add(r[1]); });
const nodes = [...names].map((n) => ({
  name: n,
  itemStyle: { color: colour[n] || '#C4B5FD', borderWidth: 0 },
  label: { position: entry.has(n) ? 'left' : 'right' },
}));
return {
  backgroundColor: 'transparent',
  tooltip: { trigger: 'item', valueFormatter: (x) => Number(x).toFixed(3) + ' req/s' },
  series: [{
    type: 'sankey', left: 100, right: 230, top: 8, bottom: 8, nodeWidth: 10, nodeGap: 10,
    draggable: false, emphasis: { focus: 'adjacency' },
    label: { color: '#C9D2DE', fontFamily: 'Inter, sans-serif', fontSize: 12,
      formatter: (p) => p.name + '  ' + Number(p.value).toFixed(2) },
    lineStyle: { color: 'source', opacity: 0.35, curveness: 0.5 },
    data: nodes,
    links: live.map((r) => ({ source: r[0], target: r[1], value: r[2] })),
  }],
};

const colour = { infra: '#7DD3FC', apps: '#F59E0B', sandbox: '#C4B5FD' };
const tree = {};
let total = 0;
context.panel.data.series.forEach((s) => {
  const pool = s.fields.find((f) => f.name === 'pool');
  const ns = s.fields.find((f) => f.name === 'namespace');
  const v = s.fields.find((f) => f.type === 'number');
  if (!ns || !v) return;
  for (let i = 0; i < v.values.length; i++) {
    const p = (pool && pool.values[i]) || 'no pool label';
    (tree[p] = tree[p] || []).push({ name: ns.values[i], value: v.values[i] });
    total += v.values[i];
  }
});
if (!total) {
  return { title: { text: 'No memory reported in this range', left: 'center', top: 'middle',
    textStyle: { color: '#8D99AB', fontSize: 13, fontWeight: 'normal' } } };
}
const gib = (b) => (b / 2 ** 30).toFixed(2) + ' GiB';
const data = Object.keys(tree).sort().map((p) => ({
  name: p,
  itemStyle: { color: colour[p] || '#8D99AB' },
  children: tree[p].sort((a, b) => b.value - a.value).map((k) => ({
    ...k, itemStyle: { color: colour[p] || '#8D99AB', opacity: 0.55 },
  })),
}));
return {
  backgroundColor: 'transparent',
  tooltip: { trigger: 'item', formatter: (p) => p.name + ': ' + gib(p.value) },
  graphic: [{ type: 'text', left: 'center', top: 'middle',
    style: { text: (total / 2 ** 30).toFixed(1) + '\nGiB in use', fill: '#E7ECF3', align: 'center',
      font: '600 18px "Roboto Mono", ui-monospace, monospace', lineHeight: 22 } }],
  series: [{
    type: 'sunburst', radius: ['34%', '92%'], data, sort: null,
    itemStyle: { borderColor: '#0D1218', borderWidth: 2 },
    label: { color: '#0D1218', fontSize: 11, minAngle: 14, rotate: 'tangential' },
    levels: [{}, { label: { color: '#0D1218', fontWeight: 600 } }, { label: { color: '#E7ECF3' } }],
  }],
};
